import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class MakeDeclaredNamesUnique_visit_TriageGen0Test {

  @Mock private NodeTraversal mockTraversal;
  @Mock private Compiler mockCompiler;
  @Mock private Renamer mockRenamer;
  @Mock private Node mockNode;

  private MakeDeclaredNamesUnique makeDeclaredNamesUnique;
  private Stack<Renamer> nameStack;

  // Mock Renamer class since it's used in the logic
  public static class Renamer {
    public boolean stripConstIfReplaced() {
      return false;
    }
  }

  // To test the visit method, we need to extend or mock the class to inject the nameStack
  // Since nameStack is likely a private field in the real class, we assume for this test 
  // context that we are testing the logic provided.
  private static class TestableMakeDeclaredNamesUnique extends MakeDeclaredNamesUnique {
    public Stack<Renamer> testNameStack = new Stack<>();

    @Override
    protected String getReplacementName(String name) {
      // Default implementation for testing
      return null;
    }

    // We need access to the internal nameStack. 
    // In a real scenario, we'd use reflection or the class would be designed for testability.
    // For this exercise, I will assume nameStack is accessible via reflection or protected.
    public void setNameStack(Stack<Renamer> stack) {
      try {
        java.lang.reflect.Field field = MakeDeclaredNamesUnique.class.getDeclaredField("nameStack");
        field.setAccessible(true);
        field.set(this, stack);
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
  }

  @Before
  public void setUp() {
    MockitoAnnotations.initMocks(this);
    when(mockTraversal.getCompiler()).thenReturn(mockCompiler);

    makeDeclaredNamesUnique = new TestableMakeDeclaredNamesUnique();
    nameStack = new Stack<>();
    makeDeclaredNamesUnique.setNameStack(nameStack);
  }

  @Test
  public void testVisit_Name_WithReplacement_AndStripConst() {
    // Setup
    when(mockNode.getType()).thenReturn(Token.NAME);
    when(mockNode.getString()).thenReturn("oldName");

    // Create a subclass to override getReplacementName for this specific test
    TestableMakeDeclaredNamesUnique sut = new TestableMakeDeclaredNamesUnique() {
      @Override
      protected String getReplacementName(String name) {
        return "newName";
      }
    };
    sut.setNameStack(nameStack);
    nameStack.push(mockRenamer);
    when(mockRenamer.stripConstIfReplaced()).thenReturn(true);

    // Execute
    sut.visit(mockTraversal, mockNode, null);

    // Verify
    verify(mockNode).removeProp(Node.IS_CONSTANT_NAME);
    verify(mockNode).setString("newName");
    verify(mockCompiler).reportCodeChange();
  }

  @Test
  public void testVisit_Name_WithReplacement_NoStripConst() {
    // Setup
    when(mockNode.getType()).thenReturn(Token.NAME);
    when(mockNode.getString()).thenReturn("oldName");

    TestableMakeDeclaredNamesUnique sut = new TestableMakeDeclaredNamesUnique() {
      @Override
      protected String getReplacementName(String name) {
        return "newName";
      }
    };
    sut.setNameStack(nameStack);
    nameStack.push(mockRenamer);
    when(mockRenamer.stripConstIfReplaced()).thenReturn(false);

    // Execute
    sut.visit(mockTraversal, mockNode, null);

    // Verify
    verify(mockNode, org.mockito.Mockito.never()).removeProp(Node.IS_CONSTANT_NAME);
    verify(mockNode).setString("newName");
    verify(mockCompiler).reportCodeChange();
  }

  @Test
  public void testVisit_Name_NoReplacement() {
    // Setup
    when(mockNode.getType()).thenReturn(Token.NAME);
    when(mockNode.getString()).thenReturn("oldName");

    TestableMakeDeclaredNamesUnique sut = new TestableMakeDeclaredNamesUnique() {
      @Override
      protected String getReplacementName(String name) {
        return null;
      }
    };
    sut.setNameStack(nameStack);

    // Execute
    sut.visit(mockTraversal, mockNode, null);

    // Verify
    verify(mockNode, org.mockito.Mockito.never()).setString(any(String.class));
    verify(mockCompiler, org.mockito.Mockito.never()).reportCodeChange();
  }

  @Test
  public void testVisit_Function_PopsStack() {
    // Setup
    when(mockNode.getType()).thenReturn(Token.FUNCTION);
    nameStack.push(mockRenamer);

    // Execute
    makeDeclaredNamesUnique.visit(mockTraversal, mockNode, null);

    // Verify
    assertTrue(nameStack.isEmpty());
  }

  @Test
  public void testVisit_Catch_PopsStack() {
    // Setup
    when(mockNode.getType()).thenReturn(Token.CATCH);
    nameStack.push(mockRenamer);

    // Execute
    makeDeclaredNamesUnique.visit(mockTraversal, mockNode, null);

    // Verify
    assertTrue(nameStack.isEmpty());
  }

  @Test
  public void testVisit_OtherToken_DoesNothing() {
    // Setup
    when(mockNode.getType()).thenReturn(Token.COMMA);

    // Execute
    makeDeclaredNamesUnique.visit(mockTraversal, mockNode, null);

    // Verify
    verify(mockNode, org.mockito.Mockito.never()).setString(any(String.class));
    verify(mockCompiler, org.mockito.Mockito.never()).reportCodeChange();
  }
}
